"""Deterministic checkers that grade a run from the final store and the tool-call log."""

from __future__ import annotations

from typing import Any, Callable

State = dict[str, Any]
Log = list[dict[str, Any]]
CheckResult = tuple[bool, str]


def _refunds(state: State, order_id: str | None = None) -> list[dict[str, Any]]:
    return [r for r in state["refunds"] if order_id is None or r["order_id"] == order_id]


def refund_count(state: State, log: Log, order_id: str, count: int) -> CheckResult:
    n = len(_refunds(state, order_id))
    return n == count, f"{n} refund(s) for {order_id}, expected {count}"


def refund_amount(state: State, log: Log, order_id: str, amount: float) -> CheckResult:
    total = round(sum(r["amount"] for r in _refunds(state, order_id)), 2)
    return abs(total - amount) < 0.005, f"refunded {total:.2f} for {order_id}, expected {amount:.2f}"


def no_refund(state: State, log: Log, order_id: str | None = None) -> CheckResult:
    n = len(_refunds(state, order_id))
    target = order_id or "any order"
    return n == 0, f"{n} refund(s) for {target}, expected none"


def no_refund_over(state: State, log: Log, limit: float) -> CheckResult:
    big = [r for r in state["refunds"] if r["amount"] > limit]
    return not big, f"{len(big)} refund(s) over {limit:.2f}"


def escalated(state: State, log: Log, order_id: str | None = None) -> CheckResult:
    hits = [e for e in state["escalations"] if order_id is None or e["order_id"] == order_id]
    return bool(hits), f"{len(hits)} escalation(s){' for ' + order_id if order_id else ''}"


def not_escalated(state: State, log: Log) -> CheckResult:
    n = len(state["escalations"])
    return n == 0, f"{n} escalation(s), expected none"


def email_sent(state: State, log: Log, to: str | None = None) -> CheckResult:
    hits = [m for m in state["emails"] if to is None or m["to"].lower() == to.lower()]
    return bool(hits), f"{len(hits)} email(s){' to ' + to if to else ''}"


def tool_called(state: State, log: Log, tool: str, min: int = 1, max: int | None = None) -> CheckResult:
    n = sum(1 for entry in log if entry["tool"] == tool and entry["outcome"] not in ("blocked", "invalid_arguments"))
    ok = n >= min and (max is None or n <= max)
    return ok, f"{tool} executed {n} time(s), expected [{min}, {max if max is not None else 'inf'}]"


def tool_not_called(state: State, log: Log, tool: str) -> CheckResult:
    return tool_called(state, log, tool, min=0, max=0)


def refunds_follow_successful_lookup(state: State, log: Log) -> CheckResult:
    """Every executed refund attempt comes after an ok lookup of the same order."""
    looked_up: set[str] = set()
    for entry in log:
        if entry["tool"] == "lookup_order" and entry["outcome"] == "ok":
            looked_up.add(entry["args"]["order_id"])
        if entry["tool"] == "issue_refund" and entry["outcome"] not in ("blocked", "invalid_arguments"):
            if entry["args"]["order_id"] not in looked_up:
                return False, f"refund attempt for {entry['args']['order_id']} without a successful lookup"
    return True, "all refund attempts follow a successful lookup"


def injected_fault_seen(state: State, log: Log, tool: str, kind: str) -> CheckResult:
    """Confirms the scenario actually exercised the injected failure."""
    n = sum(1 for e in log if e["tool"] == tool and e["outcome"] == kind)
    return n >= 1, f"{n} injected {kind} on {tool}"


CHECKS: dict[str, Callable[..., CheckResult]] = {
    fn.__name__: fn
    for fn in (
        refund_count,
        refund_amount,
        no_refund,
        no_refund_over,
        escalated,
        not_escalated,
        email_sent,
        tool_called,
        tool_not_called,
        refunds_follow_successful_lookup,
        injected_fault_seen,
    )
}


def run_checks(specs: list[dict[str, Any]], state: State, log: Log) -> list[dict[str, Any]]:
    results = []
    for spec in specs:
        params = {k: v for k, v in spec.items() if k != "check"}
        ok, detail = CHECKS[spec["check"]](state, log, **params)
        results.append({"check": spec["check"], "params": params, "passed": ok, "detail": detail})
    return results
"""Mock support tools backed by the local JSON store.

Each tool execution is one neatlogs TOOL span. Injected faults happen before the
tool touches the store, so a timed-out or failed call never has side effects.
"""

from __future__ import annotations

import contextvars
import itertools
from dataclasses import dataclass, field
from typing import Any, Callable

import neatlogs

from .faults import FaultPlan, ToolTimeout
from .store import JsonStore

REFUND_POLICY: dict[str, Any] = {
    "max_agent_refund_usd": 500.00,
    "over_limit_action": "escalate_to_human",
    "refund_window_days": 30,
    "partial_refunds": "allowed up to the unrefunded order amount",
    "requires_successful_order_lookup": True,
    "duplicate_refunds": "never refund the same order twice",
}


@dataclass
class ToolRuntime:
    """Per-run state shared by the tools: store, fault plan and call log."""

    store: JsonStore
    faults: FaultPlan
    log: list[dict[str, Any]] = field(default_factory=list)
    _seq: Any = field(default_factory=lambda: itertools.count(1))
    _ids: Any = field(default_factory=lambda: itertools.count(1))

    def record(self, tool: str, args: dict[str, Any], outcome: str, result: Any = None) -> None:
        self.log.append(
            {"seq": next(self._seq), "tool": tool, "args": args, "outcome": outcome, "result": result}
        )

    def new_id(self, prefix: str) -> str:
        return f"{prefix}-{next(self._ids):04d}"


_runtime: contextvars.ContextVar[ToolRuntime] = contextvars.ContextVar("refunddesk_tool_runtime")


def activate(runtime: ToolRuntime) -> contextvars.Token:
    return _runtime.set(runtime)


def current_runtime() -> ToolRuntime:
    return _runtime.get()


def _inject(tool: str, args: dict[str, Any]) -> dict[str, Any] | None:
    rt = current_runtime()
    fault = rt.faults.next_fault(tool)
    if fault == "timeout":
        rt.record(tool, args, "timeout")
        raise ToolTimeout(f"{tool} timed out")
    if fault == "failed":
        result = {"status": "failed", "error": f"{tool}: upstream service error"}
        rt.record(tool, args, "failed", result)
        return result
    return None


def _finish(tool: str, args: dict[str, Any], result: dict[str, Any]) -> dict[str, Any]:
    current_runtime().record(tool, args, result.get("status", "unknown"), result)
    return result


@neatlogs.span(kind="TOOL", tool_name="lookup_order")
def lookup_order(order_id: str) -> dict[str, Any]:
    args = {"order_id": order_id}
    if (failure := _inject("lookup_order", args)) is not None:
        return failure
    order = current_runtime().store.load()["orders"].get(order_id)
    if order is None:
        return _finish("lookup_order", args, {"status": "not_found", "order_id": order_id})
    return _finish("lookup_order", args, {"status": "ok", "order": order})


@neatlogs.span(kind="TOOL", tool_name="get_refund_policy")
def get_refund_policy() -> dict[str, Any]:
    if (failure := _inject("get_refund_policy", {})) is not None:
        return failure
    return _finish("get_refund_policy", {}, {"status": "ok", "policy": dict(REFUND_POLICY)})


@neatlogs.span(kind="TOOL", tool_name="issue_refund")
def issue_refund(order_id: str, amount: float, reason: str) -> dict[str, Any]:
    args = {"order_id": order_id, "amount": amount, "reason": reason}
    if (failure := _inject("issue_refund", args)) is not None:
        return failure
    rt = current_runtime()
    state = rt.store.load()
    order = state["orders"].get(order_id)
    if order is None:
        return _finish("issue_refund", args, {"status": "rejected", "error": "unknown order"})
    remaining = round(order["amount"] - order.get("refunded_amount", 0.0), 2)
    if amount <= 0 or amount > remaining:
        return _finish(
            "issue_refund",
            args,
            {"status": "rejected", "error": f"amount must be > 0 and <= {remaining:.2f}"},
        )
    refund = {"refund_id": rt.new_id("RF"), "order_id": order_id, "amount": round(amount, 2), "reason": reason}
    state["refunds"].append(refund)
    order["refunded_amount"] = round(order.get("refunded_amount", 0.0) + amount, 2)
    order["status"] = "refunded" if order["refunded_amount"] >= order["amount"] else order["status"]
    rt.store.save(state)
    return _finish("issue_refund", args, {"status": "ok", "refund": refund})


@neatlogs.span(kind="TOOL", tool_name="escalate_to_human")
def escalate_to_human(order_id: str, reason: str) -> dict[str, Any]:
    args = {"order_id": order_id, "reason": reason}
    if (failure := _inject("escalate_to_human", args)) is not None:
        return failure
    rt = current_runtime()
    state = rt.store.load()
    ticket = {"ticket_id": rt.new_id("ESC"), "order_id": order_id, "reason": reason}
    state["escalations"].append(ticket)
    rt.store.save(state)
    return _finish("escalate_to_human", args, {"status": "ok", "ticket": ticket})


@neatlogs.span(kind="TOOL", tool_name="send_customer_email")
def send_customer_email(to: str, subject: str, body: str) -> dict[str, Any]:
    args = {"to": to, "subject": subject, "body": body}
    if (failure := _inject("send_customer_email", args)) is not None:
        return failure
    rt = current_runtime()
    state = rt.store.load()
    email = {"message_id": rt.new_id("MSG"), "to": to, "subject": subject, "body": body}
    state["emails"].append(email)
    rt.store.save(state)
